<script setup lang="ts">
import {ref,computed,onMounted,onBeforeUnmount,nextTick,watch} from 'vue'
import {api} from '../api'
import type {ImageHistoryItem} from '../types'
import Icon from './Icon.vue'
import {historyDay,historyTime} from '../history-time'
const props=defineProps<{activeId?:string;activeTitle?:string;ready?:Promise<unknown>}>()
const emit=defineEmits<{close:[];open:[id:string];changed:[item:ImageHistoryItem];deleted:[ids:string[]]}>()
const items=ref<ImageHistoryItem[]>([]),loading=ref(true),working=ref(false),error=ref(''),batch=ref(false),selected=ref<string[]>([]),menu=ref<string>(),search=ref('')
const dialog=ref<{kind:'rename'|'delete';ids:string[];name:string}>(),name=ref(''),nameInput=ref<HTMLInputElement>()
const currentTime=ref(Date.now())
let clockTimer:ReturnType<typeof setInterval>|undefined
const groups=computed(()=>{
 const day=historyDay,today=day(currentTime.value),yesterday=day(currentTime.value-86400000)
 const labels=['置顶','今天','昨天','更早'],result=labels.map(label=>({label,items:[] as ImageHistoryItem[]}))
 for(const item of [...items.value].sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt))){if(search.value&&!item.title.toLowerCase().includes(search.value.toLowerCase()))continue;const date=day(item.updatedAt);result[item.pinned?0:date===today?1:date===yesterday?2:3]!.items.push(item)}return result.filter(g=>g.items.length)
})
const allPinned=computed(()=>selected.value.length>0&&selected.value.every(id=>items.value.find(i=>i.id===id)?.pinned))
watch(()=>props.activeTitle,title=>{if(title)items.value=items.value.map(i=>i.id===props.activeId?{...i,title}:i)})
let disposed=false
async function load(){loading.value=true;error.value='';try{await props.ready;if(disposed)return;const result=await api.imageHistory();if(!disposed)items.value=result}catch(e){if(!disposed)error.value=String(e instanceof Error?e.message:e)}finally{if(!disposed)loading.value=false}}
function toggle(id:string){selected.value=selected.value.includes(id)?selected.value.filter(i=>i!==id):[...selected.value,id]}
function leaveBatch(){batch.value=false;selected.value=[]}
function choose(item:ImageHistoryItem){if(batch.value)toggle(item.id);else emit('open',item.id)}
async function pin(ids:string[],pinned:boolean){working.value=true;menu.value=undefined;error.value='';try{for(const id of ids){const item=await api.sessionMetadata(id,{pinned});items.value=items.value.map(i=>i.id===id?item:i);emit('changed',item)}}catch(e){error.value=e instanceof Error?e.message:'操作失败，请重试'}finally{working.value=false}}
async function confirm(kind:'rename'|'delete',ids:string[]){menu.value=undefined;dialog.value={kind,ids,name:items.value.find(i=>i.id===ids[0])?.title||''};name.value=dialog.value.name;await nextTick();if(kind==='rename'){nameInput.value?.focus();nameInput.value?.select()}else document.querySelector<HTMLButtonElement>('.history-confirm-close')?.focus()}
async function commit(){const d=dialog.value;if(!d||working.value)return;working.value=true;error.value='';try{if(d.kind==='rename'){const item=await api.sessionMetadata(d.ids[0]!,{title:name.value.trim()});items.value=items.value.map(i=>i.id===item.id?item:i);emit('changed',item)}else{for(const id of d.ids){await api.remove(id);items.value=items.value.filter(i=>i.id!==id);selected.value=selected.value.filter(i=>i!==id);emit('deleted',[id])}}dialog.value=undefined}catch(e){error.value=e instanceof Error?e.message:'操作失败，请重试'}finally{working.value=false}}
function escape(){if(working.value)return;if(dialog.value)dialog.value=undefined;else if(menu.value)menu.value=undefined;else if(batch.value)leaveBatch();else emit('close')}
function dialogKey(event:KeyboardEvent){if(event.key==='Escape'){event.preventDefault();escape();return}if(event.key!=='Tab')return;const controls=Array.from((event.currentTarget as HTMLElement).querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled)'));const first=controls[0],last=controls.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus()}}
onMounted(()=>{load();clockTimer=setInterval(()=>currentTime.value=Date.now(),60000)})
onBeforeUnmount(()=>{disposed=true;clearInterval(clockTimer)})
</script>
<template>
 <section class="image-history" aria-label="历史会话记录" @keydown.esc.stop.prevent="escape" @pointerdown.stop @click="menu=undefined">
  <header class="history-heading"><div class="history-heading-title"><span>会话记录</span><h3>{{batch?'已选择 '+selected.length+' 个对话':'历史对话'}}</h3></div><button v-if="!batch" type="button" aria-label="批量操作" data-tooltip="批量操作" :disabled="loading||working||!items.length" @click="batch=true"><Icon name="settings" :size="18"/></button><button type="button" :aria-label="batch?'退出批量操作':'返回对话'" :data-tooltip="batch?'退出批量操作':'返回对话'" :disabled="working" @click="batch?leaveBatch():emit('close')"><Icon :name="batch?'close':'back'" :size="19"/></button></header>
  <label class="history-search"><Icon name="search" :size="16"/><input v-model="search" aria-label="搜索历史对话" placeholder="搜索会话名称"/></label>
  <p v-if="error" class="history-error" role="alert">{{error}} <button v-if="!dialog" @click="load">重试</button></p>
  <div class="history-scroll"><p v-if="loading" class="history-empty">正在读取会话…</p><p v-else-if="!groups.length" class="history-empty">{{search?'没有匹配的会话':'还没有历史会话，发送消息后会自动保存。'}}</p>
   <section v-for="group in groups" :key="group.label" class="history-group"><h4>{{group.label}}</h4><div v-for="item in group.items" :key="item.id" class="history-row" :class="{active:props.activeId===item.id,selected:selected.includes(item.id)}"><button class="history-title" :disabled="working" :aria-label="batch?'选择 '+item.title:'打开 '+item.title" :aria-pressed="batch?selected.includes(item.id):undefined" @click="choose(item)"><span v-if="batch" class="history-checkbox" :class="{checked:selected.includes(item.id)}"><Icon v-if="selected.includes(item.id)" name="check" :size="13"/></span><span>{{item.title}}</span><span v-if="item.hasVoiceCall" class="history-call-badge" aria-label="语音通话"><Icon name="voiceCall" :size="15"/></span></button><div v-if="!batch" class="history-row-tail" :class="{open:menu===item.id}"><time :datetime="item.updatedAt">{{historyTime(item.updatedAt,currentTime)}}</time><button type="button" class="history-more" :aria-label="'会话操作 '+item.title" data-tooltip="会话操作" :aria-expanded="menu===item.id" :disabled="working" @click.stop="menu=menu===item.id?undefined:item.id"><span class="history-more-dots" aria-hidden="true"><i/><i/><i/></span></button></div><div v-if="menu===item.id" class="history-menu" role="menu" :aria-label="item.title+' 操作'" @click.stop><button role="menuitem" @click="confirm('rename',[item.id])"><Icon name="edit" :size="16"/>重命名</button><button role="menuitem" @click="pin([item.id],!item.pinned)"><Icon name="pin" :size="16"/>{{item.pinned?'取消置顶':'置顶'}}</button><button role="menuitem" class="danger" @click="confirm('delete',[item.id])"><Icon name="trash" :size="16"/>删除</button></div></div></section>
  </div>
  <footer v-if="batch"><button :disabled="!selected.length||working" @click="pin([...selected],!allPinned)"><Icon name="pin" :size="18"/>{{allPinned?'取消置顶':'置顶'}}</button><button class="danger" :disabled="!selected.length||working" @click="confirm('delete',[...selected])"><Icon name="trash" :size="18"/>删除</button></footer>
  <Teleport to="body"><div v-if="dialog" class="image-chat-lightbox history-confirm-backdrop" @pointerdown.stop @keydown.esc.stop.prevent="escape"><section class="history-confirm" role="dialog" aria-modal="true" :aria-label="dialog.kind==='rename'?'重命名会话':'删除会话确认'" @keydown.stop="dialogKey"><button class="history-confirm-close" aria-label="关闭确认弹框" :disabled="working" @click="dialog=undefined"><Icon name="close" :size="20"/></button><span class="history-dialog-icon"><Icon :name="dialog.kind==='rename'?'edit':'trash'" :size="24"/></span><small>会话管理</small><h3>{{dialog.kind==='rename'?'重命名会话':dialog.ids.length>1?'删除 '+dialog.ids.length+' 个会话':'删除会话'}}</h3><p>{{dialog.kind==='rename'?'使用简短清晰的名称，方便以后查找。':'删除后将无法恢复，确认删除所选会话及其对话记录？'}}</p><label v-if="dialog.kind==='rename'">会话名称<div class="history-name-input"><input ref="nameInput" v-model="name" maxlength="40" aria-label="会话名称" :disabled="working" @keydown.enter.prevent="name.trim()&&commit()"/><span>{{name.length}} / 40</span></div></label><p v-else class="history-delete-name">{{dialog.ids.length===1?dialog.name:'已选择 '+dialog.ids.length+' 个会话'}}</p><p v-if="error" class="history-error" role="alert">{{error}}</p><footer><button :disabled="working" @click="dialog=undefined">取消</button><button class="history-confirm-primary" :class="{danger:dialog.kind==='delete'}" :disabled="working||(dialog.kind==='rename'&&!name.trim())" @click="commit">{{working?'处理中…':dialog.kind==='rename'?'保存名称':'确认删除'}}</button></footer></section></div></Teleport>
 </section>
</template>
